$SUDO chmod 755 "$DEST"
$SUDO find "$DEST" -type d -exec chmod 755 {} +
$SUDO find "$DEST" -type f -exec chmod 644 {} +
test -f "$DEST/index.html" && test -f "$DEST/js/main.js" || { echo "Copia dell'app non riuscita."; exit 1; }

# scarica un gruppo di file da una CDN e li accetta solo se l'impronta SHA-256 coincide
install_assets() {
  local label="$1" base="$2" sub="$3" manifest="$4" tmp ok=1 sum fpath
  tmp="$(mktemp -d)"
  while read -r sum fpath; do
    [ -z "${fpath:-}" ] && continue
    mkdir -p "$tmp/$(dirname "$fpath")"
    if ! curl -fsSL --max-time 90 "$base/$fpath" -o "$tmp/$fpath" 2>/dev/null; then echo "   Download non riuscito: $fpath"; ok=0; break; fi
    if [ "$(sha256sum "$tmp/$fpath" | cut -d' ' -f1)" != "$sum" ]; then echo "   Impronta diversa dal previsto: $fpath (file scartato)"; ok=0; break; fi
  done <<< "$manifest"
  if [ "$ok" = 1 ]; then
    $SUDO mkdir -p "$DEST/$sub"; $SUDO cp -r "$tmp/." "$DEST/$sub/"; $SUDO chmod -R a+rX "$DEST/$sub"
    echo "   $label attivato."
  else
    echo "   $label NON installato: l'app funziona, ma questa funzione resta disattivata."
  fi
  rm -r "$tmp"
}

